import React from 'react';

import clsx from 'clsx';

import { dateRangeToLocaleString } from '@helpers/dateHelper';
import PohAva from '@ui-kit/Ava';

import styles from './styles.module.less';
import { IBaseHiking } from '../../@types/hikingList.types';

interface IHikingBadgeProps extends React.HTMLAttributes<HTMLDivElement> {
  hiking: IBaseHiking;
}

const HikingBadge: React.FC<IHikingBadgeProps> = ({ hiking, className, ...rest }) => {
  return (
    <div {...rest} className={clsx('d-flex align-items-center', styles.hikingBadge, className)}>
      <PohAva colorize alt={hiking.name} src={hiking.ava} />
      <div className="ms-2" style={{ lineHeight: 1.2 }}>
        <strong className="d-block text-truncate">{hiking.name}</strong>
        <small className="text-muted">{dateRangeToLocaleString(hiking.start, hiking.finish)}</small>
      </div>
    </div>
  );
};

export const HikingBadgeOneLine: React.FC<IHikingBadgeProps> = ({ hiking, className, ...rest }) => {
  return (
    <div
      title={dateRangeToLocaleString(hiking.start, hiking.finish)}
      {...rest}
      className={clsx('d-inline-flex align-items-center', className)}
    >
      <PohAva colorize alt={hiking.name} width={'1em'} src={hiking.ava} />
      <div className="ms-1" style={{ lineHeight: '1em' }}>
        <small className="d-block text-truncate">{hiking.name}</small>
      </div>
    </div>
  );
};

export default HikingBadge;
